### **A) Bell-LaPadula Runtime Check**[2]
```zig
// MINDEN ACCESS REQUEST-nél FUT:
pub fn verifyPolicy(self: *Self, subject: *const Principal, 
                   object: *const SecureObject, right: AccessRight) !bool {
    // Step 1: Matrix check
    const matrixcheck = self.matrix.hasRight(subject.id, object.id, right);
    try self.proofsteps.append(step1);

    // Step 2: BLP simple security check
    const blpreadok = self.blpmodel.canRead(subject.id, object.id);

    // Step 3: BLP *-property check  
    const blpwriteok = self.blpmodel.canWrite(subject.id, object.id);

    // Step 4: Biba integrity check
    const bibaok = self.bibamodel.canRead(subject.id, object.id);

    // Step 5: Final decision
    const finalresult = matrixcheck or policyallows and clearancecheck;
    return finalresult;
}
```

### **B) Non-Interference Runtime Proof**[2]
```zig
// MINDEN STATE CHANGE-nél ELLENŐRZI:
pub fn proveNonInterference(self: *Self, initialstate: *const SystemState,
                           alternatestate: *const SystemState) !bool {
    // Step 1: Partition variables HIGH vs LOW
    try proof.addStep("Partition variables into high and low sets", ...);

    // Step 2: Bisimulation check
    const bisimilar = try self.bisimulation.areBisimilar(
        initialstate, alternatestate, self.property.observerlevel
    );

    // Step 3: Unwinding lemma
    if (bisimilar) {
        try self.bisimulation.addPair(initialstate, alternatestate);
    }

    // Step 4: Conclusion + cryptographic binding
    self.isproven = bisimilar;
    return bisimilar;
}
```

### **C) Integrity Hash Chain Runtime**[2]
