// MINDEN DATA WRITE-nál FUT:
pub fn registerData(self: *Self, data: []const u8) !u64 {
    const id = self.nextid;
    self.nextid += 1;

    // 1️⃣ Hash computation
    var hash: [32]u8 = undefined;
    Sha256.hash(data, &hash, .{});

    // 2️⃣ Store in hash map
    try self.datahashes.put(id, hash);

    // 3️⃣ Append to blockchain-style chain
    try self.hashchain.append(data);

    return id;
}
