pub fn performVerifiedInference(input, outputbuf) !void {
    // 1️⃣ Cryptographic commitment
    const inputcommit = self.commitmentscheme.commit(input);

    // 2️⃣ Proof of correctness recording (minden step)
    try self.proofofcorrectness.recordStep(...);

    // 3️⃣ Differential privacy (Laplace noise)
