### **A) RSF Network - Saját Architektúra**[1]

```zig
// RSF: Scatter → Transform → Gather
pub fn rsf_forward(weights, x1, x2) (y1, y2) {
    // 1️⃣ SCATTER STEP
    s_out = matrix_mul(weights.s_weight, x2);
    s_bias_added = vector_add(s_out, weights.s_bias);
    s_exp = vector_exp(s_bias_added);  // Activation
    y1 = vector_mul(x1, s_exp);        // Modulate x1

    // 2️⃣ TRANSFORM STEP
    t_out = matrix_mul(weights.t_weight, y1);
    t_bias_added = vector_add(t_out, weights.t_bias);
    y2 = vector_add(x2, t_bias_added); // Residual

    return (y1, y2);
}

// MULTI-LAYER NETWORK
pub const RSFNetwork = struct {
    layers: []RSFLayerState,  // 4-48 layers

    pub fn forward(self, x1, x2) (y1, y2) {
        // Chainelt forward pass minden layeren keresztül
        for (self.layers) |layer| {
            (x1, x2) = rsf_forward(layer.weights, x1, x2);
        }
        return (x1, x2);
    }
};
```

