### **C) Training Loop - Teljes Pipeline**[1]

```zig
pub fn trainJaideRSF(
    allocator, mgt, rsf, proj, optimizer, 
    samples, config
) !void {
    // EPOCH LOOP
    for (0..config.numepochs) |epoch| {
        var epoch_loss: f64 = 0.0;

        // BATCH LOOP
        for (samples) |sample| {
            // 1️⃣ Embedding létrehozás
            var input = try createEmbeddingInPlace(...);
            defer input.deinit();

            // 2️⃣ FORWARD PASS
            try rsf.forward(input);
            var logits = try proj.forward(input);  // vocab projection

            // 3️⃣ LOSS SZÁMÍTÁS (cross-entropy)
            const target_token = sample.tokens[context_len];
            var max_logit = max(logits);
            var sum_exp = sum(exp(logits - max_logit));
            const log_prob = logits[target_idx] - max_logit - log(sum_exp);
            batch_loss += -log_prob;

            // 4️⃣ BACKPROPAGATION
            // Projection layer gradients
            var probs = softmax(logits);
            probs[target_idx] -= 1.0;  // gradient

            for (vocabsize) |vi| {
                proj.bias.data[vi] -= lr * probs[vi];
                for (hdim) |hi| {
                    proj.weights[hi*vocab + vi] -= lr * probs[vi] * input[hi];
                }
            }

            // RSF layer gradients (implicit via backprop)
            for (rsf.layers) |*layer| {
                layer.sweight.data[idx] -= rsf_lr * grad * input[j];
                layer.sbias.data[i] -= rsf_lr * grad;
                // ... tweight, tbias ugyanígy
            }

            // 5️⃣ OPTIMIZER STEP (SFD)
            try optimizer.update(gradients, params, lr);
        }

        // 6️⃣ CHECKPOINT MENTÉS
        try saveModels(allocator, rsf, mgt, optimizer, config.modelsdir);

        std.debug.print("Epoch {d}: Loss {d:.6}\n", .{epoch+1, avg_loss});
    }
}
