### **D) Inference/Generation - Text Generálás**[1]

```zig
fn generateRespone(
    allocator, rsf, proj, mgt, 
    prompt: []const u8, 
    max_len: usize
) ![]const u8 {
    // 1️⃣ TOKENIZE INPUT
    var tokens = ArrayList(u32).init(allocator);
    try mgt.encode(prompt, &tokens);

    var generated = ArrayList(u32).init(allocator);
    try generated.appendSlice(tokens.items);

    // 2️⃣ AUTOREGRESSIVE GENERATION
    var step: usize = 0;
    while (step < max_len) : (step += 1) {
        // Context window (max DIM tokens)
        const context_start = if (generated.items.len > dim) 
            generated.items.len - dim 
        else 0;
        const context = generated.items[context_start..];

        // 3️⃣ FORWARD PASS
        var input = try createEmbeddingInPlace(context, vocab, dim);
        defer input.deinit();

        try rsf.forward(input);
        var logits = try allocator.alloc(f32, vocab);
        defer allocator.free(logits);

        proj.forward(input, logits);

        // 4️⃣ NEXT TOKEN SAMPLING
        const next_token = softmaxArgMax(logits);  // greedy
        if (next_token == 0) break;  // EOS

        try generated.append(next_token);
    }

    // 5️⃣ DECODE TO TEXT
    var output = ArrayList(u8).init(allocator);
    try mgt.decode(generated.items, &output);
    return output.toOwnedSlice();
}
```

