    // REPL LOOP
    while (true) {
        const line = try stdin.readUntilDelimiterOrEof(&line_buf, '\n');
        if (line == null) break;

        const input = std.mem.trim(u8, line.?, &std.ascii.whitespace);
        if (input.len == 0) continue;
        if (std.mem.eql(u8, input, "exit")) break;

        // GENERATE RESPONSE
