### **Runtime Checks Minden Inference-nél:**[3]

```zig
pub fn performVerifiedInference(self, input, output_buf) !void {
    // 1️⃣ Input commitment
    const input_commitment = try self.commitInput(input);

    // 2️⃣ RSF forward pass
    try self.rsf.forward(input);

    // 3️⃣ Proof recording
    try self.proof_of_correctness.recordStep(
        1, input, intermediate, .MatrixMultiply
    );

    // 4️⃣ Differential Privacy noise
    for (output_buf) |*val| {
        const noisy = self.differential_privacy.addLaplaceNoise(val.*);
        val.* = @floatCast(noisy);
    }

    // 5️⃣ ZK Proof (optional)
    if (self.use_zk_proofs) {
        const proof = try self.zk_prover.proveInference(
            input, output_buf, weights_s, weights_t
        );
        try self.inference_proofs.append(proof);
    }

    // 6️⃣ Verification counter
    self.verification_count += 1;
    if (try self.verifyProofOfCorrectness()) {
        self.successful_verifications += 1;
    }
}
